const $=(s)=>document.querySelector(s),$$=(s)=>[...document.querySelectorAll(s)],root=document.documentElement;
const races=[{no:'01',pass:'AKINA PASS',distance:'5.8 KM',condition:'DRY',winner:'HATCH'},{no:'04',pass:'USUI RIDGE',distance:'6.2 KM',condition:'FOG',winner:'WHITE'},{no:'07',pass:'MYOGI LINE',distance:'7.1 KM',condition:'DAMP',winner:'DOWNHILL'},{no:'11',pass:'AKAGI ROUTE',distance:'8.4 KM',condition:'COLD',winner:'OLD SCHOOL'}];
let lastY=scrollY,velocity=0,targetX=0,targetY=0,easedX=0,easedY=0;
addEventListener('mousemove',e=>{targetX=e.clientX/innerWidth-.5;targetY=e.clientY/innerHeight-.5;root.style.setProperty('--mx',e.clientX+'px');root.style.setProperty('--my',e.clientY+'px');$('.cursor').dataset.label=e.target.closest('[data-cursor]')?.dataset.cursor||''});
requestAnimationFrame(function camera(){easedX+=(targetX-easedX)*.075;easedY+=(targetY-easedY)*.075;root.style.setProperty('--cx',easedX.toFixed(4));root.style.setProperty('--cy',easedY.toFixed(4));requestAnimationFrame(camera)});
addEventListener('scroll',()=>{velocity+=((scrollY-lastY)-velocity)*.22;lastY=scrollY;root.style.setProperty('--velocity',Math.min(Math.abs(velocity),80));root.style.setProperty('--page-y',scrollY.toFixed(1));const speed=Math.round(118+Math.min(Math.abs(velocity)*2.7,102));$$('[data-speed]').forEach(n=>n.textContent=speed);const sections=$$('[data-section]');let near=sections[0];sections.forEach(s=>{const box=s.getBoundingClientRect(),progress=Math.max(0,Math.min(1,(innerHeight-box.top)/(innerHeight+box.height)));s.style.setProperty('--scene',progress.toFixed(4));if(Math.abs(box.top)<Math.abs(near.getBoundingClientRect().top))near=s});$('.counter').textContent=`${near?.dataset.section||'01'} / 10`},{passive:true});
$$('[data-race]').forEach(b=>{const activate=()=>{const r=races[+b.dataset.race];$$('[data-race]').forEach(x=>x.classList.toggle('active',x===b));$('[data-race-no]').textContent=r.no;$('[data-race-pass]').textContent=r.pass;$('[data-distance]').textContent=r.distance;$('[data-condition]').textContent=r.condition;$('[data-winner]').textContent=r.winner};b.onmouseenter=activate;b.onfocus=activate;b.onclick=activate});
$$('[data-race]')[0]?.classList.add('active');
$('.rivals').onpointermove=e=>{const r=e.currentTarget.getBoundingClientRect();e.currentTarget.style.setProperty('--px',(e.clientX-r.left)/r.width-.5)};
if(window.Lenis){const lenis=new Lenis({duration:1.15,smoothWheel:true});requestAnimationFrame(function raf(t){lenis.raf(t);requestAnimationFrame(raf)})}
if(window.gsap&&window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);gsap.to('.hero-car',{xPercent:12,scale:1.08,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}});gsap.to('.hero-copy',{xPercent:-15,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1.2}});gsap.to('.route-line',{strokeDashoffset:0,scrollTrigger:{trigger:'.akina',start:'top 70%',end:'bottom 45%',scrub:1}});gsap.utils.toArray('.reveal').forEach(el=>gsap.fromTo(el,{y:80,opacity:0},{y:0,opacity:1,duration:1,scrollTrigger:{trigger:el,start:'top 85%'}}))}
const canvas=$('.road-canvas'),ctx=canvas.getContext('2d');let phase=0,rafId=0;function resize(){const d=Math.min(devicePixelRatio,1.5);canvas.width=innerWidth*d;canvas.height=innerHeight*d;canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.setTransform(d,0,0,d,0,0)}function road(){const w=innerWidth,h=innerHeight;phase+=.018+Math.min(Math.abs(velocity)*.0015,.18);ctx.clearRect(0,0,w,h);let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#030303');sky.addColorStop(1,'#121212');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle='#0a0a0a';ctx.beginPath();ctx.moveTo(0,h*.38);for(let x=0;x<=w;x+=50)ctx.lineTo(x,h*(.3+Math.sin(x*.009)*.08));ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.fillStyle='#181818';ctx.beginPath();ctx.moveTo(w*.44,h*.42);ctx.lineTo(w*.56,h*.42);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(245,245,240,.75)';ctx.lineWidth=2;for(let i=0;i<16;i++){const z=(i/16+phase)%1,y=h*.42+z*z*h*.64,half=3+Math.pow(z,1.8)*w*.34;ctx.globalAlpha=z;ctx.beginPath();ctx.moveTo(w/2-half,y);ctx.lineTo(w/2-half-25*z,y+16+z*45);ctx.stroke();ctx.beginPath();ctx.moveTo(w/2+half,y);ctx.lineTo(w/2+half+25*z,y+16+z*45);ctx.stroke()}ctx.globalAlpha=1;ctx.fillStyle='#d90000';ctx.shadowColor='#d90000';ctx.shadowBlur=18;ctx.fillRect(w*.475,h*.47,8,4);ctx.fillRect(w*.52,h*.47,8,4);ctx.shadowBlur=0;rafId=requestAnimationFrame(road)}resize();addEventListener('resize',resize);road();
